# model_registry.tf -- o Model Package Group, e quem pode mudar o status

resource "aws_sagemaker_model_package_group" "fraude_checkout" {
  model_package_group_name        = "fraude-checkout"
  model_package_group_description = "Modelo de risco de fraude no checkout (L73 -> L75)"

  tags = {
    Projeto = var.projeto
    Time    = "risco-e-ml"
  }
}

# Politica do grupo: quem pode LER versoes e quem pode MUDAR ApprovalStatus.
# Sem isto, qualquer principal com sagemaker:UpdateModelPackage na conta
# consegue aprovar o proprio modelo -- o mesmo problema do PassRole sem
# Resource do L54, so que aplicado a aprovacao em vez de identidade de deploy.
data "aws_iam_policy_document" "aprovar_modelo" {
  statement {
    sid       = "AprovarVersao"
    effect    = "Allow"
    actions   = ["sagemaker:UpdateModelPackage", "sagemaker:DescribeModelPackage"]
    resources = ["${aws_sagemaker_model_package_group.fraude_checkout.arn}/*"]

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.revisor_risco.arn] # so o papel do revisor, nunca a conta inteira
    }
  }
}

resource "aws_sagemaker_model_package_group_policy" "fraude_checkout" {
  model_package_group_name = aws_sagemaker_model_package_group.fraude_checkout.model_package_group_name
  resource_policy          = data.aws_iam_policy_document.aprovar_modelo.json
}

# pipeline_promocao.tf

resource "aws_codepipeline" "promocao_modelo" {
  name     = "${var.projeto}-promocao-fraude-checkout"
  role_arn = aws_iam_role.deploy_pipeline.arn # a MESMA role federada por OIDC do L54

  artifact_store {
    location = aws_s3_bucket.artefatos_pipeline.bucket
    type     = "S3"
  }

  stage {
    name = "Origem"
    action {
      name             = "NovoPacotePendente"
      category         = "Source"
      owner            = "AWS"
      provider         = "EventBridge"
      version          = "1"
      output_artifacts = ["pacote_pendente"]
    }
  }

  stage {
    name = "Aprovacao"
    action {
      name     = "RevisarBaselineEAprovar"
      category = "Approval"
      owner    = "AWS"
      provider = "Manual"
      version  = "1"
      configuration = {
        # O revisor ve este texto na hora de decidir -- e por isso o pacote
        # carrega o baseline como metadata, nao so a metrica que melhorou.
        CustomData = "Compare auc_offline com baseline_producao_auc e baseline_producao_chargeback_pct antes de aprovar."
      }
    }
  }

  stage {
    name = "Promover"
    action {
      name            = "AtualizarEndpointBlueGreen"
      category        = "Build"
      owner           = "AWS"
      provider        = "CodeBuild"
      version         = "1"
      input_artifacts = ["pacote_pendente"]
      configuration = {
        ProjectName = aws_codebuild_project.promover_endpoint.name
      }
    }
  }
}

# Dispara a pipeline no instante em que um Model Package novo entra como
# PendingManualApproval -- ninguem precisa lembrar de rodar isto a mao.
resource "aws_cloudwatch_event_rule" "novo_pacote_pendente" {
  name = "${var.projeto}-novo-pacote-modelo"
  event_pattern = jsonencode({
    source        = ["aws.sagemaker"]
    "detail-type" = ["SageMaker Model Package State Change"]
    detail = {
      ModelPackageGroupName = [aws_sagemaker_model_package_group.fraude_checkout.model_package_group_name]
      ModelApprovalStatus   = ["PendingManualApproval"]
    }
  })
}

resource "aws_cloudwatch_event_target" "dispara_pipeline" {
  rule     = aws_cloudwatch_event_rule.novo_pacote_pendente.name
  arn      = aws_codepipeline.promocao_modelo.arn
  role_arn = aws_iam_role.eventbridge_para_pipeline.arn
}

# endpoint_blue_green.tf

resource "aws_cloudwatch_metric_alarm" "erro_variante_nova" {
  alarm_name          = "${var.projeto}-fraude-checkout-erro-variante-nova"
  comparison_operator = "GreaterThanThreshold"
  evaluation_periods  = 2
  metric_name         = "Invocation5XXErrors"
  namespace           = "AWS/SageMaker"
  period              = 60
  statistic           = "Sum"
  threshold           = 5 # mais de 5 erros 5xx por minuto, duas vezes seguidas

  dimensions = {
    EndpointName = "fraude-checkout"
    VariantName  = "candidata"
  }
}

resource "aws_sagemaker_endpoint" "fraude_checkout" {
  name                 = "fraude-checkout"
  endpoint_config_name = aws_sagemaker_endpoint_configuration.candidata.name

  deployment_config {
    blue_green_update_policy {
      traffic_routing_configuration {
        type                     = "CANARY"
        wait_interval_in_seconds = 600 # 10 min de bake antes de subir o peso

        canary_size {
          type  = "CAPACITY_PERCENT"
          value = 10
        }
      }
      termination_wait_in_seconds = 300 # a variante antiga so sai depois desta folga
    }

    auto_rollback_configuration {
      alarms {
        alarm_name = aws_cloudwatch_metric_alarm.erro_variante_nova.alarm_name
      }
    }
  }
}

// FraudeCheckoutClient.cs -- o consumidor nao muda nada durante a promocao
public sealed class FraudeCheckoutClient
{
    private readonly IAmazonSageMakerRuntime _runtime;
    private const string EndpointName = "fraude-checkout"; // nunca muda, mesmo em rollback

    public FraudeCheckoutClient(IAmazonSageMakerRuntime runtime) => _runtime = runtime;

    public async Task<ScoreFraude> AvaliarAsync(Pedido pedido, CancellationToken ct)
    {
        var payload = JsonSerializer.SerializeToUtf8Bytes(pedido.ParaFeatures());

        var resposta = await _runtime.InvokeEndpointAsync(new InvokeEndpointRequest
        {
            EndpointName = EndpointName, // o peso entre variantes decide quem responde
            ContentType  = "application/json",
            Body         = new MemoryStream(payload)
        }, ct);

        return ScoreFraude.Desserializar(resposta.Body);
        // Se um rollback automatico disparar no meio de uma promocao, este codigo
        // nao percebe: o nome do endpoint e identico antes, durante e depois.
    }
}
